std::vector<EventSchema> schemas_for_platform(const std::string& platform) {
    std::vector<EventSchema> out;
    for (const auto& schema : event_schemas()) {
        if (core::lower(schema.platform) == core::lower(platform)) out.push_back(schema);
    }
    return out;
}

std::vector<ArtifactProfile> profiles_for_family(const std::string& family) {
    std::vector<ArtifactProfile> out;
    for (const auto& profile : artifact_profiles()) {
        if (core::lower(profile.family) == core::lower(family)) out.push_back(profile);
    }
    return out;
}

std::vector<ResponseAction> actions_for_phase(const std::string& phase) {
    std::vector<ResponseAction> out;
    for (const auto& action : response_actions()) {
        if (core::lower(action.phase) == core::lower(phase)) out.push_back(action);
    }
    return out;
}

std::string catalog_summary() {
    std::map<std::string, std::size_t> by_platform;
    std::map<std::string, std::size_t> by_family;
    std::map<std::string, std::size_t> by_phase;
    for (const auto& schema : event_schemas()) by_platform[schema.platform]++;
    for (const auto& profile : artifact_profiles()) by_family[profile.family]++;
    for (const auto& action : response_actions()) by_phase[action.phase]++;
    std::ostringstream out;
    out << "event_schemas=" << event_schemas().size();
    out << " artifact_profiles=" << artifact_profiles().size();
    out << " response_actions=" << response_actions().size();
    for (const auto& kv : by_platform) out << "\nplatform." << kv.first << "=" << kv.second;
    for (const auto& kv : by_family) out << "\nfamily." << kv.first << "=" << kv.second;
    for (const auto& kv : by_phase) out << "\nphase." << kv.first << "=" << kv.second;
    return out.str();
}

